static lstr L909 = {0, 3351, "\012// Parses s in the given base into *out. On failure sets *err and returns false.\012static bool narra_int_parse(lstr* s, int64_t base, int64_t* out, lstr** err) {\012  if (base < 2 || base > 36) { *err = lstr_from_cstr(\"base must be between 2 and 36\"); return false; }\012  int64_t i = 0;\012  bool neg = false;\012  if (s->len > 0 && s->data[0] == '-') { neg = true; i = 1; }\012  if (i >= s->len) { *err = lstr_from_cstr(s->len == 0 \077 \"empty string\" : \"no digits after '-'\"); return false; }\012  uint64_t limit = neg \077 (uint64_t)INT64_MAX + 1 : (uint64_t)INT64_MAX;\012  uint64_t acc = 0;\012  for (; i < s->len; i++) {\012    char ch = s->data[i];\012    int64_t d;\012    if (ch >= '0' && ch <= '9') d = ch - '0';\012    else if (ch >= 'a' && ch <= 'z') d = ch - 'a' + 10;\012    else if (ch >= 'A' && ch <= 'Z') d = ch - 'A' + 10;\012    else d = 99;\012    if (d >= base) { *err = lstr_from_cstr(\"invalid digit for the base\"); return false; }\012    if (acc > (limit - (uint64_t)d) / (uint64_t)base) { *err = lstr_from_cstr(\"number does not fit in 64 bits\"); return false; }\012    acc = acc * (uint64_t)base + (uint64_t)d;\012  }\012  *out = neg \077 (int64_t)(0 - acc) : (int64_t)acc;\012  return true;\012}\012\012static lstr* narra_int_to_hex(int64_t n) {\012  char buf[24];\012  uint64_t m = n < 0 \077 0 - (uint64_t)n : (uint64_t)n;\012  int pos = (int)sizeof buf;\012  buf[--pos] = 0;\012  do { buf[--pos] = \"0123456789abcdef\"[m & 15]; m >>= 4; } while (m != 0);\012  if (n < 0) buf[--pos] = '-';\012  return lstr_from_cstr(buf + pos);\012}\012\012// Parses s in the given base into *out for a sized integer type of `bits` bits, signed or\012// not. The value comes back as the 64 bits of its two's complement. On failure sets *err\012// and returns false; a value outside the type's range says the range.\012static bool narra_sized_parse(lstr* s, int64_t base, int64_t bits, bool is_signed, uint64_t* out, lstr** err) {\012  if (base < 2 || base > 36) { *err = lstr_from_cstr(\"base must be between 2 and 36\"); return false; }\012  int64_t i = 0;\012  bool neg = false;\012  if (s->len > 0 && s->data[0] == '-') { neg = true; i = 1; }\012  if (i >= s->len) { *err = lstr_from_cstr(s->len == 0 \077 \"empty string\" : \"no digits after '-'\"); return false; }\012  uint64_t all_ones = bits == 64 \077 UINT64_MAX : ((uint64_t)1 << bits) - 1;\012  uint64_t limit = is_signed \077 (neg \077 ((uint64_t)1 << (bits - 1)) : ((uint64_t)1 << (bits - 1)) - 1) : (neg \077 0 : all_ones);\012  uint64_t acc = 0;\012  bool overflow = false;\012  for (; i < s->len; i++) {\012    char ch = s->data[i];\012    int64_t d;\012    if (ch >= '0' && ch <= '9') d = ch - '0';\012    else if (ch >= 'a' && ch <= 'z') d = ch - 'a' + 10;\012    else if (ch >= 'A' && ch <= 'Z') d = ch - 'A' + 10;\012    else d = 99;\012    if (d >= base) { *err = lstr_from_cstr(\"invalid digit for the base\"); return false; }\012    if (!overflow) {\012      if ((uint64_t)d > limit || acc > (limit - (uint64_t)d) / (uint64_t)base) overflow = true;\012      else acc = acc * (uint64_t)base + (uint64_t)d;\012    }\012  }\012  if (overflow) {\012    char buf[96];\012    if (is_signed) {\012      uint64_t half = (uint64_t)1 << (bits - 1);\012      snprintf(buf, sizeof buf, \"number does not fit in %d bits (-%\" PRIu64 \" to %\" PRIu64 \")\", (int)bits, half, half - 1);\012    } else {\012      snprintf(buf, sizeof buf, \"number does not fit in %d bits (0 to %\" PRIu64 \")\", (int)bits, all_ones);\012    }\012    *err = lstr_from_cstr(buf);\012    return false;\012  }\012  *out = neg \077 0 - acc : acc;\012  return true;\012}\012"};
