static lstr L10224 = {0, 1368, "// std/atomic: Atomic<T>, a bool or an integer with atomic operations (SPEC.md\012// section 8, D111 item 4).\012//\012// T is bool or an integer type up to 64 bits (E1411 otherwise). Every\012// operation is sequentially consistent. Copies of an Atomic are handles to\012// one value. Importing this module builds the program in thread mode (D111\012// item 2).\012\012import * as Boxes from \"std/box\"\012import * as Threads from \"std/internal/thread\"\012\012export opaque struct Atomic<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Atomic<T> uses alloc {\012  return Atomic { slot: Boxes.new(value) }\012}\012\012export function load<T>(atomic: Atomic<T>): T {\012  return Threads.atomicLoad(atomic.slot)\012}\012\012export function store<T>(atomic: Atomic<T>, value: T) {\012  Threads.atomicStore(atomic.slot, value)\012}\012\012// Stores value and gives the value it replaced.\012export function exchange<T>(atomic: Atomic<T>, value: T): T {\012  return Threads.atomicExchange(atomic.slot, value)\012}\012\012// Adds amount and gives the old value. The sum wraps, like + (D92).\012export function add<T>(atomic: Atomic<T>, amount: T): T {\012  return Threads.atomicAdd(atomic.slot, amount)\012}\012\012// Stores replacement when the value is expected, and tells whether it stored.\012export function compareExchange<T>(atomic: Atomic<T>, expected: T, replacement: T): bool {\012  return Threads.atomicCompareExchange(atomic.slot, expected, replacement)\012}\012"};
static lstr L10225 = {0, 9, "std/build"};
static lstr L10226 = {0, 1133, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012}\012\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012}\012\012export const os: Os = Os.Linux\012export const arch: Arch = Arch.X86_64\012export const debug: bool = true\012\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
