static lstr L10228 = {0, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
static lstr L10229 = {0, 11, "std/channel"};
static lstr L10230 = {0, 5375, "// std/channel: bounded channels between threads (SPEC.md section 8, D111 item 4).\012//\012// Channel.create gives a Sender and a Receiver over one queue of a fixed\012// number of slots. send blocks while the queue is full, receive blocks while it\012// is empty. Copies of an end share it; when the last copy of the sender is\012// dropped the channel closes, and when the last copy of the receiver is\012// dropped send gives false. Importing this module builds the program in thread\012// mode (D111 item 2).\012\012import * as Arrays from \"std/array\"\012import * as Boxes from \"std/box\"\012import * as CellSlot from \"std/internal/cell\"\012import * as Threads from \"std/internal/thread\"\012\012// The conditions of the Sync: a value was queued (or the channel closed), and\012// a slot was freed.\012const VALUE_READY = 0\012const ROOM_READY = 1\012\012// The end counts of the Sync.\012const SENDERS = 0\012const RECEIVERS = 1\012\012// Where the oldest value is, how many values wait, and whether close ran.\012// Read and written only with the lock held.\012struct QueueState {\012  head: int\012  count: int\012  closed: bool\012}\012\012// The ring of slots, each a box of its own, so a send or a receive writes one\012// slot in place and never copies the ring.\012struct Queue<T> {\012  sync: Sync\012  state: Box<QueueState>\012  slots: Array<Box<Option<T>>>\012}\012\012export opaque struct Sender<T> {\012  queue: Queue<T>\012  end: Sync\012}\012\012export opaque struct Receiver<T> {\012  queue: Queue<T>\012  end: Sync\012}\012\012// A channel with room for capacity values; a capacity below 1 is 1. The\012// element type must be Sendable (E1190).\012export function create<T>(capacity: int): #[Sender<T>, Receiver<T>] uses alloc {\012  let size = capacity\012  if (size < 1) {\012    size = 1\012  }\012  let slots: Array<Box<Option<T>>> = []\012  for (let index = 0; index < size; index++) {\012    const slot: Box<Option<T>> = Boxes.new(None)\012    Arrays.push(mutable slots, slot)\012  }\012  const sync = Threads.sync()\012  const queue = Queue {\012    sync: sync,\012    state: Boxes.new(QueueState { head: 0, count: 0, closed: false }),\012    slots: slots,\012  }\012  const sender = Sender { queue: queue, end: Threads.end(sync, SENDERS) }\012  const receiver = Receiver { queue: queue, end: Threads.end(sync, RECEIVERS) }\012  return #[sender, receiver]\012}\012\012// Queues value, waiting while the channel is full. Gives false, and keeps\012// nothing, once the channel is closed or every receiver is gone.\012export function send<T>(sender: Sender<T>, value: T): bool uses io {\012  const queue = sender.queue\012  // The value is marked shared before a receiver on another thread can reach it.\012  Threads.share(value)\012  Threads.lock(queue.sync)\012  while (canSend(queue) && queue.state.value.count == Arrays.length(queue.slots)) {\012    Threads.wait(queue.sync, ROOM_READY)\012  }\012  if (!canSend(queue)) {\012    Threads.unlock(queue.sync)\012    return false\012  }\012  const state = queue.state.value\012  const tail = wrapSlot(state.head + state.count, Arrays.length(queue.slots))\012  CellSlot.store(queue.slots[tail], Some(value))\012  CellSlot.store(queue.state, QueueState {\012    head: state.head,\012    count: state.count + 1,\012    closed: false,\012  })\012  Threads.wakeOne(queue.sync, VALUE_READY)\012  Threads.unlock(queue.sync)\012  return true\012}\012\012// Takes the oldest value, waiting while the channel is empty. Gives None once\012// the channel is closed and empty.\012export function receive<T>(receiver: Receiver<T>): Option<T> uses io {\012  const queue = receiver.queue\012  Threads.lock(queue.sync)\012  while (queue.state.value.count == 0 && isOpen(queue)) {\012    Threads.wait(queue.sync, VALUE_READY)\012  }\012  if (queue.state.value.count == 0) {\012    Threads.unlock(queue.sync)\012    return None\012  }\012  const state = queue.state.value\012  // The value moves out of its slot, so the receiver holds the only reference.\012  const value = Threads.take(queue.slots[state.head])\012  CellSlot.store(queue.state, QueueState {\012    head: wrapSlot(state.head + 1, Arrays.length(queue.slots)),\012    count: state.count - 1,\012    closed: state.closed,\012  })\012  Threads.wakeOne(queue.sync, ROOM_READY)\012  Threads.unlock(queue.sync)\012  return value\012}\012\012// The values of the channel, in the order they were sent, until it is closed and empty.\012export function* values<T>(receiver: Receiver<T>): Generator<T> uses io {\012  let open = true\012  while (open) {\012    const next = receive(receiver)\012    if (next is Some(value)) {\012      yield value\012    } else {\012      open = false\012    }\012  }\012}\012\012// Closes the channel for every copy of the sender. The values already queued\012// can still be received.\012export function close<T>(sender: Sender<T>) {\012  const queue = sender.queue\012  Threads.lock(queue.sync)\012  const state = queue.state.value\012  CellSlot.store(queue.state, QueueState { head: state.head, count: state.count, closed: true })\012  Threads.wakeAll(queue.sync, VALUE_READY)\012  Threads.wakeAll(queue.sync, ROOM_READY)\012  Threads.unlock(queue.sync)\012}\012\012// With the lock held: the channel takes values while it is not closed and a receiver is left.\012function canSend<T>(queue: Queue<T>): bool {\012  return !queue.state.value.closed && Threads.ends(queue.sync, RECEIVERS) > 0\012}\012\012// With the lock held: more values can come while it is not closed and a sender is left.\012function isOpen<T>(queue: Queue<T>): bool {\012  return !queue.state.value.closed && Threads.ends(queue.sync, SENDERS) > 0\012}\012\012// The slot a position past the end of the ring comes back to.\012function wrapSlot(position: int, size: int): int {\012  if (size == 0) {\012    return 0\012  }\012  return position % size\012}\012"};
