static lstr L10234 = {0, 1182, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012export opaque struct CString {\012  text: string\012}\012\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text: text })\012}\012\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
