static lstr L10270 = {0, 8368, "// std/terminal: detecting a terminal and styling text for it (D118 item 7).\012//\012// The style functions always add the codes and have no effect beyond `alloc`, so\012// tests can compare styled output. The caller decides whether to style:\012// `const color = Terminal.useColor(Stream.Stderr)`. A style closes with its own\012// reset code and reopens itself after an inner close, so a styled part inside\012// another styled part does not end the outer one.\012\012import * as Tty from \"std/internal/terminal\"\012import * as Env from \"std/env\"\012import * as Int from \"std/int\"\012import * as Str from \"std/string\"\012\012export enum Stream {\012  Stdin\012  Stdout\012  Stderr\012}\012\012export enum Color {\012  Default\012  Black\012  Red\012  Green\012  Yellow\012  Blue\012  Magenta\012  Cyan\012  White\012  BrightBlack\012  BrightRed\012  BrightGreen\012  BrightYellow\012  BrightBlue\012  BrightMagenta\012  BrightCyan\012  BrightWhite\012  Ansi256(index: u8)\012  Rgb(red: u8, green: u8, blue: u8)\012}\012\012export struct Style {\012  foreground: Color = Color.Default\012  background: Color = Color.Default\012  bold: bool = false\012  dim: bool = false\012  italic: bool = false\012  underline: bool = false\012  inverse: bool = false\012  strikethrough: bool = false\012}\012\012function streamDescriptor(stream: Stream): int {\012  return match (stream) { Stream.Stdin => 0, Stream.Stdout => 1, Stream.Stderr => 2 }\012}\012\012export function isTerminal(stream: Stream): bool uses io {\012  return Tty.isTerminal(streamDescriptor(stream))\012}\012\012export function columns(stream: Stream): Option<int> uses io {\012  const width = Tty.columns(streamDescriptor(stream))\012  if (width > 0) {\012    return Some(width)\012  }\012  return None\012}\012\012export function useColor(stream: Stream): bool uses io, alloc {\012  // NO_COLOR wins, then FORCE_COLOR, then a dumb terminal, then the stream itself.\012  if (Env.get(\"NO_COLOR\") is Some(noColor)) {\012    if (noColor != \"\") {\012      return false\012    }\012  }\012  if (Env.get(\"FORCE_COLOR\") is Some(forceColor)) {\012    if (forceColor != \"\" && forceColor != \"0\") {\012      return true\012    }\012  }\012  if (Env.get(\"TERM\") is Some(term)) {\012    if (term == \"dumb\") {\012      return false\012    }\012  }\012  return isTerminal(stream)\012}\012\012const ESCAPE = \"\\u{1b}[\"\012\012function sequence(code: string): string uses alloc {\012  return `${ESCAPE}${code}m`\012}\012\012// Wraps the text in an open and a close code. A close inside the text is replaced\012// by `reopen`, which ends the inner style and starts this one again.\012function wrap(text: string, open: string, close: string, reopen: string): string uses alloc {\012  return `${open}${Str.replace(text, close, reopen)}${close}`\012}\012\012function paint(text: string, openCode: string, closeCode: string): string uses alloc {\012  const open = sequence(openCode)\012  const close = sequence(closeCode)\012  return wrap(text, open, close, open)\012}\012\012// Bold and dim share the close code 22, so closing one also ends the other.\012function paintWeight(text: string, openCode: string): string uses alloc {\012  const open = sequence(openCode)\012  const close = sequence(\"22\")\012  return wrap(text, open, close, `${close}${open}`)\012}\012\012export function bold(text: string): string uses alloc {\012  return paintWeight(text, \"1\")\012}\012\012export function dim(text: string): string uses alloc {\012  return paintWeight(text, \"2\")\012}\012\012export function italic(text: string): string uses alloc {\012  return paint(text, \"3\", \"23\")\012}\012\012export function underline(text: string): string uses alloc {\012  return paint(text, \"4\", \"24\")\012}\012\012export function inverse(text: string): string uses alloc {\012  return paint(text, \"7\", \"27\")\012}\012\012export function strikethrough(text: string): string uses alloc {\012  return paint(text, \"9\", \"29\")\012}\012\012export function black(text: string): string uses alloc {\012  return paint(text, \"30\", \"39\")\012}\012\012export function red(text: string): string uses alloc {\012  return paint(text, \"31\", \"39\")\012}\012\012export function green(text: string): string uses alloc {\012  return paint(text, \"32\", \"39\")\012}\012\012export function yellow(text: string): string uses alloc {\012  return paint(text, \"33\", \"39\")\012}\012\012export function blue(text: string): string uses alloc {\012  return paint(text, \"34\", \"39\")\012}\012\012export function magenta(text: string): string uses alloc {\012  return paint(text, \"35\", \"39\")\012}\012\012export function cyan(text: string): string uses alloc {\012  return paint(text, \"36\", \"39\")\012}\012\012export function white(text: string): string uses alloc {\012  return paint(text, \"37\", \"39\")\012}\012\012export function gray(text: string): string uses alloc {\012  return paint(text, \"90\", \"39\")\012}\012\012export function bgBlack(text: string): string uses alloc {\012  return paint(text, \"40\", \"49\")\012}\012\012export function bgRed(text: string): string uses alloc {\012  return paint(text, \"41\", \"49\")\012}\012\012export function bgGreen(text: string): string uses alloc {\012  return paint(text, \"42\", \"49\")\012}\012\012export function bgYellow(text: string): string uses alloc {\012  return paint(text, \"43\", \"49\")\012}\012\012export function bgBlue(text: string): string uses alloc {\012  return paint(text, \"44\", \"49\")\012}\012\012export function bgMagenta(text: string): string uses alloc {\012  return paint(text, \"45\", \"49\")\012}\012\012export function bgCyan(text: string): string uses alloc {\012  return paint(text, \"46\", \"49\")\012}\012\012export function bgWhite(text: string): string uses alloc {\012  return paint(text, \"47\", \"49\")\012}\012\012// The SGR parameters that select the color; `offset` is 0 for a foreground and 10 for a background.\012function colorCode(color: Color, offset: int): string uses alloc {\012  const base = 38 + offset\012  return match (color) {\012    Color.Default => Int.toString(39 + offset)\012    Color.Black => Int.toString(30 + offset)\012    Color.Red => Int.toString(31 + offset)\012    Color.Green => Int.toString(32 + offset)\012    Color.Yellow => Int.toString(33 + offset)\012    Color.Blue => Int.toString(34 + offset)\012    Color.Magenta => Int.toString(35 + offset)\012    Color.Cyan => Int.toString(36 + offset)\012    Color.White => Int.toString(37 + offset)\012    Color.BrightBlack => Int.toString(90 + offset)\012    Color.BrightRed => Int.toString(91 + offset)\012    Color.BrightGreen => Int.toString(92 + offset)\012    Color.BrightYellow => Int.toString(93 + offset)\012    Color.BrightBlue => Int.toString(94 + offset)\012    Color.BrightMagenta => Int.toString(95 + offset)\012    Color.BrightCyan => Int.toString(96 + offset)\012    Color.BrightWhite => Int.toString(97 + offset)\012    Color.Ansi256(index) => `${Int.toString(base)};5;${Int.toString(Int.from(index))}`\012    Color.Rgb(\012      red,\012      green,\012      blue,\012    ) => `${Int.toString(base)};2;${Int.toString(Int.from(red))};${Int.toString(Int.from(green))};${Int.toString(Int.from(blue))}`\012  }\012}\012\012// A field left as its default (`Color.Default`, `false`) adds nothing. Applies every field of the style in turn, so the pieces nest like the plain functions.\012export function style(text: string, look: Style): string uses alloc {\012  let result = text\012  if (look.bold) {\012    result = bold(result)\012  }\012  if (look.dim) {\012    result = dim(result)\012  }\012  if (look.italic) {\012    result = italic(result)\012  }\012  if (look.underline) {\012    result = underline(result)\012  }\012  if (look.inverse) {\012    result = inverse(result)\012  }\012  if (look.strikethrough) {\012    result = strikethrough(result)\012  }\012  if (!(look.foreground is Color.Default)) {\012    result = paint(result, colorCode(look.foreground, 0), \"39\")\012  }\012  if (!(look.background is Color.Default)) {\012    result = paint(result, colorCode(look.background, 10), \"49\")\012  }\012  return result\012}\012\012// Removes the SGR sequences (`ESC [ <digits and semicolons> m`) and keeps everything else.\012export function stripStyles(text: string): string uses alloc {\012  const length = Str.length(text)\012  let builder = Str.builder()\012  let start = 0\012  let index = 0\012  while (index < length) {\012    if (Str.byteAt(text, index) == 27 && index + 1 < length && Str.byteAt(text, index + 1) == 91) {\012      // Scan the parameters; the sequence counts only when an `m` ends it.\012      let end = index + 2\012      while (end < length && isParameterByte(Str.byteAt(text, end))) {\012        end += 1\012      }\012      if (end < length && Str.byteAt(text, end) == 109) {\012        if (Str.slice(text, start, index) is Some(kept)) {\012          Str.append(mutable builder, kept)\012        }\012        start = end + 1\012        index = end + 1\012        continue\012      }\012    }\012    index += 1\012  }\012  Str.append(mutable builder, Str.sliceFrom(text, start))\012  return Str.build(builder)\012}\012\012function isParameterByte(byte: int): bool {\012  // Digits, the semicolon and the colon of the `38:5:1` form.\012  return (byte >= 48 && byte <= 57) || byte == 59 || byte == 58\012}\012"};
