static lstr L10272 = {0, 3032, "// std/thread: threads that run in a scope (SPEC.md section 8, D111).\012//\012// Thread.scope gives a Scope, Thread.start runs a function on a new thread of\012// that scope, and Thread.join waits for it and gives its result. Every thread\012// a scope started has ended when Thread.scope returns. Importing this module\012// builds the program in thread mode (D111 item 2).\012\012import * as Boxes from \"std/box\"\012import * as CellSlot from \"std/internal/cell\"\012import * as Threads from \"std/internal/thread\"\012\012// The thread number of the runtime and whether a join has waited for it. Only\012// the thread that started it reads or writes this box.\012struct ThreadControl {\012  id: int\012  joined: bool\012}\012\012// The threads started in a scope, newest first, so a start adds one in place\012// of copying a list.\012enum ThreadList {\012  Started(control: Box<ThreadControl>, earlier: ThreadList)\012  Empty\012}\012\012// The threads of a scope, so the scope can join those not joined yet.\012export opaque struct Scope {\012  threads: Box<ThreadList>\012}\012\012// A running or ended thread. The thread writes its result into the result box\012// once, before it ends; join reads it only after waiting for the end.\012export opaque struct Thread<T> {\012  result: Box<Option<T>>\012  control: Box<ThreadControl>\012}\012\012// Calls body with a new scope and gives its result once every thread started\012// in the scope has ended.\012export function scope<T, effect E>(body: (threadScope: Scope) => T uses E): T uses E, alloc {\012  const opened = Scope { threads: Boxes.new(ThreadList.Empty) }\012  const result = body(opened)\012  let pending = opened.threads.value\012  let walking = true\012  while (walking) {\012    match (pending) {\012      ThreadList.Started(control, earlier) => {\012        joinControl(control)\012        pending = earlier\012      }\012      ThreadList.Empty => {\012        walking = false\012      }\012    }\012  }\012  return result\012}\012\012// Runs work on a new thread of the scope, with an 8 MiB stack. A work that\012// returns nothing gives a Thread<void>, whose join returns nothing.\012export function start<T, effect E>(\012  threadScope: Scope,\012  escaping work: () => T uses E,\012): Thread<T> uses E, alloc {\012  const result: Box<Option<T>> = Boxes.new(None)\012  const id = Threads.start(() => CellSlot.store(result, Some(work())))\012  const control = Boxes.new(ThreadControl { id: id, joined: false })\012  CellSlot.store(threadScope.threads, ThreadList.Started(control, threadScope.threads.value))\012  return Thread { result: result, control: control }\012}\012\012// Waits until the thread has ended and gives its result. A second join gives\012// the same value without waiting.\012export function join<T>(thread: Thread<T>): T from thread {\012  joinControl(thread.control)\012  // A thread always writes its result before it ends; a panic ends the process.\012  // For a Thread<void> there is no value and join returns nothing.\012  return Threads.result(thread.result)\012}\012\012function joinControl(control: Box<ThreadControl>) {\012  if (!control.value.joined) {\012    Threads.join(control.value.id)\012    CellSlot.store(control, ThreadControl { id: control.value.id, joined: true })\012  }\012}\012"};
